import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Version 1.0.0.40 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.40-released.md","filePath":"change-log/release/version-1.0.0.40-released.md"}'),o={name:"change-log/release/version-1.0.0.40-released.md"};function n(s,e,l,d,c,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="version-1-0-0-40-released" tabindex="-1">Version 1.0.0.40 Released <a class="header-anchor" href="#version-1-0-0-40-released" aria-label="Permalink to &quot;Version 1.0.0.40 Released&quot;">​</a></h1><p>Version <strong>1.0.0.40</strong> is a <strong>stability, market‑data, and ecosystem expansion release</strong>, focused on <strong>MultiQuote accuracy</strong>, <strong>funds &amp; margin correctness</strong>, <strong>charting APIs</strong>, and <strong>broker WebSocket maturity</strong>, along with multiple UI, sandbox, and documentation enhancements.</p><p>This release builds on the v1.0.0.39 foundation and significantly improves <strong>data correctness, options analytics, and broker parity</strong>.</p><hr><h3 id="_0-upgrade-notice" tabindex="-1"><strong>0. Upgrade Notice</strong> <a class="header-anchor" href="#_0-upgrade-notice" aria-label="Permalink to &quot;**0. Upgrade Notice**&quot;">​</a></h3><p>This release does <strong>not introduce breaking DB schema changes</strong>, but users are <strong>strongly recommended to upgrade</strong> to benefit from fixes in:</p><ul><li>Funds &amp; collateral calculations</li><li>MultiQuote accuracy</li><li>Options chain &amp; Greeks</li><li>Sandbox safety and auto‑cleanup</li></ul><p>Upgrade guide:<br><a href="https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade" target="_blank" rel="noreferrer"><strong>https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade</strong></a></p><hr><h3 id="_1-market-data-multiquote-enhancements" tabindex="-1"><strong>1. Market Data &amp; MultiQuote Enhancements</strong> <a class="header-anchor" href="#_1-market-data-multiquote-enhancements" aria-label="Permalink to &quot;**1. Market Data &amp; MultiQuote Enhancements**&quot;">​</a></h3><h4 id="multiquote-accuracy-improvements" tabindex="-1"><strong>MultiQuote Accuracy Improvements</strong> <a class="header-anchor" href="#multiquote-accuracy-improvements" aria-label="Permalink to &quot;**MultiQuote Accuracy Improvements**&quot;">​</a></h4><ul><li>Fixed <strong>OI propagation</strong> in MultiQuotes (Fyers)</li><li>Improved <strong>single‑quote routing</strong> to depth-backed quote endpoints</li><li>Stabilized quote consistency across REST &amp; WebSocket feeds</li><li>Reduced rate‑limit edge cases across brokers</li></ul><h4 id="sandbox-mode" tabindex="-1"><strong>Sandbox Mode</strong> <a class="header-anchor" href="#sandbox-mode" aria-label="Permalink to &quot;**Sandbox Mode**&quot;">​</a></h4><ul><li>Sandbox fully upgraded to <strong>MultiQuote-backed pricing</strong></li><li>Auto‑close added for <strong>expired F&amp;O contracts</strong></li><li>Improved thread safety and price validation</li></ul><hr><h3 id="_2-funds-margin-p-amp-l-fixes" tabindex="-1"><strong>2. Funds, Margin &amp; P&amp;L Fixes</strong> <a class="header-anchor" href="#_2-funds-margin-p-amp-l-fixes" aria-label="Permalink to &quot;**2. Funds, Margin &amp; P\\&amp;L Fixes**&quot;">​</a></h3><h4 id="funds-collateral" tabindex="-1"><strong>Funds &amp; Collateral</strong> <a class="header-anchor" href="#funds-collateral" aria-label="Permalink to &quot;**Funds &amp; Collateral**&quot;">​</a></h4><ul><li><strong>Angel</strong>: Collateral values in Funds API fixed</li><li><strong>Upstox</strong>: Collateral parameter corrected</li><li><strong>Samco / Wisdom / Jainam / FivePaisaXTS</strong>: Margin APIs updated and stabilized</li><li>Unified margin behavior across margin &amp; non‑margin brokers</li></ul><h4 id="p-amp-l" tabindex="-1"><strong>P&amp;L</strong> <a class="header-anchor" href="#p-amp-l" aria-label="Permalink to &quot;**P\\&amp;L**&quot;">​</a></h4><ul><li><strong>Fyers</strong>: M2M unrealized P&amp;L fixed</li><li><strong>Aliceblue</strong>: Holdings quantity &amp; P&amp;L corrections</li><li>Improved P&amp;L consistency across dashboards</li></ul><hr><h3 id="_3-options-engine-analytics" tabindex="-1"><strong>3. Options Engine &amp; Analytics</strong> <a class="header-anchor" href="#_3-options-engine-analytics" aria-label="Permalink to &quot;**3. Options Engine &amp; Analytics**&quot;">​</a></h3><h4 id="options-chain-greeks" tabindex="-1"><strong>Options Chain &amp; Greeks</strong> <a class="header-anchor" href="#options-chain-greeks" aria-label="Permalink to &quot;**Options Chain &amp; Greeks**&quot;">​</a></h4><ul><li>Fixed <strong>options chain &amp; Greeks issues</strong> (Firstock)</li><li>Migrated Greeks engine to <strong>Black‑76 (py_vollib)</strong></li><li>Added <code>forward_price</code> parameter to Greeks API</li><li>Improved intrinsic value validation before IV calculation</li><li>Deep ITM options now return <strong>theoretical Greeks instead of errors</strong></li></ul><h4 id="examples-docs" tabindex="-1"><strong>Examples &amp; Docs</strong> <a class="header-anchor" href="#examples-docs" aria-label="Permalink to &quot;**Examples &amp; Docs**&quot;">​</a></h4><ul><li>Updated Python examples for: <ul><li>Options Chain</li><li>Straddles</li><li>NIFTY‑specific Greeks</li></ul></li><li>Bruno collections updated with: <ul><li>Split size</li><li>Per‑leg expiry support</li></ul></li></ul><hr><h3 id="_4-websocket-real‐time-streaming" tabindex="-1"><strong>4. WebSocket &amp; Real‑Time Streaming</strong> <a class="header-anchor" href="#_4-websocket-real‐time-streaming" aria-label="Permalink to &quot;**4. WebSocket &amp; Real‑Time Streaming**&quot;">​</a></h3><h4 id="new-improved-websockets" tabindex="-1"><strong>New &amp; Improved WebSockets</strong> <a class="header-anchor" href="#new-improved-websockets" aria-label="Permalink to &quot;**New &amp; Improved WebSockets**&quot;">​</a></h4><ul><li><strong>Samco WebSocket</strong>: Initial implementation</li><li><strong>JainamXTS WebSockets</strong>: <ul><li>LTP fixes</li><li>Depth &amp; quote updates</li><li>Logging noise reduction</li></ul></li><li>Fixed zero‑value LTP issues (IndMoney)</li><li>Improved quote structure consistency across brokers</li></ul><h4 id="logging-performance" tabindex="-1"><strong>Logging &amp; Performance</strong> <a class="header-anchor" href="#logging-performance" aria-label="Permalink to &quot;**Logging &amp; Performance**&quot;">​</a></h4><ul><li>Startup logs moved from <code>INFO</code> → <code>DEBUG</code></li><li>Broker‑specific log filtering added</li><li>Reduced noise in high‑frequency streams</li></ul><hr><h3 id="_5-charting-strategy-apis" tabindex="-1"><strong>5. Charting &amp; Strategy APIs</strong> <a class="header-anchor" href="#_5-charting-strategy-apis" aria-label="Permalink to &quot;**5. Charting &amp; Strategy APIs**&quot;">​</a></h3><h4 id="chart-apis" tabindex="-1"><strong>Chart APIs</strong> <a class="header-anchor" href="#chart-apis" aria-label="Permalink to &quot;**Chart APIs**&quot;">​</a></h4><ul><li>Chart API structure aligned across Tradeboard</li><li>New <strong>Chart Sync API</strong> added</li><li>Improved type validation</li></ul><h4 id="strategy-infra" tabindex="-1"><strong>Strategy &amp; Infra</strong> <a class="header-anchor" href="#strategy-infra" aria-label="Permalink to &quot;**Strategy &amp; Infra**&quot;">​</a></h4><ul><li>Improved <code>.env</code> handling</li><li>Docker permission fixes for Python strategies</li><li>Railway + VPS dual deployment support</li><li>Cache restoration improvements on restart</li></ul><hr><h3 id="_6-ui-dashboard-ux" tabindex="-1"><strong>6. UI, Dashboard &amp; UX</strong> <a class="header-anchor" href="#_6-ui-dashboard-ux" aria-label="Permalink to &quot;**6. UI, Dashboard &amp; UX**&quot;">​</a></h3><ul><li>Heatmap updated</li><li>Added <strong>connected broker badge</strong></li><li>Enhanced positions page: <ul><li>Grouping</li><li>Filtering</li><li>Cleaner P&amp;L layout</li></ul></li><li>Fixed CSV export in sandbox/analyze mode</li><li>Faster UI load via CSS minification &amp; render‑blocking fixes</li></ul><hr><h3 id="_7-security-stability" tabindex="-1"><strong>7. Security &amp; Stability</strong> <a class="header-anchor" href="#_7-security-stability" aria-label="Permalink to &quot;**7. Security &amp; Stability**&quot;">​</a></h3><ul><li>Fixed critical Telegram webhook authentication issue</li><li>Upgraded vulnerable dependencies (urllib3, Werkzeug)</li><li>Improved auth caching and session expiry handling</li><li>Safer endpoint routing and validation across APIs</li></ul><hr><h3 id="_8-documentation-sdk-updates" tabindex="-1"><strong>8. Documentation &amp; SDK Updates</strong> <a class="header-anchor" href="#_8-documentation-sdk-updates" aria-label="Permalink to &quot;**8. Documentation &amp; SDK Updates**&quot;">​</a></h3><h4 id="python-sdk" tabindex="-1"><strong>Python SDK</strong> <a class="header-anchor" href="#python-sdk" aria-label="Permalink to &quot;**Python SDK**&quot;">​</a></h4><ul><li>Documentation refreshed</li><li>Examples aligned with latest APIs</li><li>Compatible with v1.0.0.40 server changes</li></ul><h4 id="docs" tabindex="-1"><strong>Docs</strong> <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;**Docs**&quot;">​</a></h4><ul><li>Expanded WebSocket documentation with performance monitoring</li><li>Cache architecture &amp; pluggable system documentation</li><li>Design documentation updates</li><li>Raspberry Pi installation guide added</li></ul><hr><h3 id="summary" tabindex="-1"><strong>Summary</strong> <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;**Summary**&quot;">​</a></h3><p>Version <strong>1.0.0.40</strong> delivers:</p><ul><li>✅ MultiQuote accuracy &amp; OI fixes</li><li>✅ Funds, collateral &amp; margin correctness across brokers</li><li>✅ Upgraded Options Greeks engine (Black‑76)</li><li>✅ New &amp; improved broker WebSockets</li><li>✅ Sandbox safety improvements</li><li>✅ Chart Sync API</li><li>✅ UI, heatmap &amp; dashboard enhancements</li><li>✅ Security hardening &amp; dependency upgrades</li><li>✅ Improved docs, examples &amp; SDK alignment</li></ul><p>This release <strong>polishes Tradeboard’s data correctness layer</strong> and <strong>raises broker parity and analytical reliability</strong>, making it safer and more accurate for <strong>live trading, scanners, and options strategies</strong>.</p><hr>',56)])])}const p=a(o,[["render",n]]);export{m as __pageData,p as default};
